const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-lifecycle", node: "Code: Parse & Validate" } });
const raw = $input.first().json;
let msg;
try {
  const payload = raw.message || raw.body || raw;
  msg = typeof payload === 'string' ? JSON.parse(payload) : payload;
} catch(e) {
  throw new Error('Malformed MQTT message: cannot parse JSON payload. ' + e.message);
}

if (!msg.action || !msg.file_hash || !msg.file_path) {
  throw new Error('Invalid lifecycle message: missing required fields (action, file_hash, file_path). Got keys: ' + JSON.stringify(Object.keys(msg)));
}

if (!['add_path', 'update_path', 'delete_file', 'remove_path'].includes(msg.action)) {
  logger.warn('[alice-dms-lifecycle] Unknown action: ' + msg.action + ' — discarding message');
  return [];
}

return [{ json: { ...msg } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-lifecycle", node: "Code: Weaviate Find by Hash" } });
const axios = require('axios');
const item = $input.first().json;
const rawHash = item.file_hash;

// BUG-4 fix: sanitize file_hash to prevent GraphQL injection
const fileHash = String(rawHash).replace(/[^a-zA-Z0-9:]/g, '');
if (fileHash !== rawHash) {
  logger.warn(`[alice-dms-lifecycle] Sanitized file_hash: '${rawHash}' -> '${fileHash}'`);
}
if (!fileHash) {
  throw new Error('file_hash is empty after sanitization, cannot query Weaviate');
}

const WEAVIATE = 'http://weaviate:8080';
// PROJ-113: Image uses snake_case field names (file_hash / file_path)
const collections = [
  { cls: 'Invoice', hashField: 'fileHash', pathField: 'filePath' },
  { cls: 'BankStatement', hashField: 'fileHash', pathField: 'filePath' },
  { cls: 'Document', hashField: 'fileHash', pathField: 'filePath' },
  { cls: 'Email', hashField: 'fileHash', pathField: 'filePath' },
  { cls: 'SecuritySettlement', hashField: 'fileHash', pathField: 'filePath' },
  { cls: 'Contract', hashField: 'fileHash', pathField: 'filePath' },
  { cls: 'Image', hashField: 'file_hash', pathField: 'file_path' }
];

let foundClass = null;
let foundId = null;
let foundAdditionalPaths = [];
let foundPathField = null;
let foundMainPath = null;
// PROJ-113: distinguish "not found anywhere" from "lookup failed" — Redis is
// only cleaned up after Weaviate was handled, never after a failed lookup.
let lookupError = false;

for (const { cls, hashField, pathField } of collections) {
  const q = `{ Get { ${cls}(where: { path: ["${hashField}"], operator: Equal, valueText: "${fileHash}" }, limit: 1) { _additional { id } ${pathField} additionalPaths } } }`;
  try {
    const r = await axios.post(`${WEAVIATE}/v1/graphql`, { query: q }, {
      headers: { 'Content-Type': 'application/json' },
      timeout: 10000
    });
    if (r.data?.errors) {
      lookupError = true;
      logger.warn(`[alice-dms-lifecycle] GraphQL error for ${cls}: ${JSON.stringify(r.data.errors)}`);
      continue;
    }
    const hits = r.data?.data?.Get?.[cls];
    if (hits && hits.length > 0) {
      foundClass = cls;
      foundId = hits[0]._additional?.id;
      foundAdditionalPaths = hits[0].additionalPaths || [];
      foundPathField = pathField;
      foundMainPath = hits[0][pathField] || null;
      break;
    }
  } catch(e) {
    lookupError = true;
    logger.warn(`[alice-dms-lifecycle] Lookup failed for ${cls}: ${e.message}`);
  }
}

if (foundId) {
  lookupError = false;
} else {
  logger.warn(`[alice-dms-lifecycle] Object not found in Weaviate for hash: ${fileHash}${lookupError ? ' (lookup incomplete)' : ''}`);
}

return [{ json: { ...item, _weaviate_class: foundClass, _weaviate_id: foundId, _existing_additional_paths: foundAdditionalPaths, _weaviate_path_field: foundPathField, _weaviate_main_path: foundMainPath, _lookup_error: lookupError } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-lifecycle", node: "Code: PATCH additionalPaths" } });
const axios = require('axios');
const item = $input.first().json;
const WEAVIATE = 'http://weaviate:8080';

if (!item._weaviate_id || !item._weaviate_class) {
  logger.warn(`[alice-dms-lifecycle] add_path: no Weaviate object found for hash ${item.file_hash}, skipping PATCH`);
  return [{ json: { ...item, _weaviate_patched: false } }];
}

const existing = Array.isArray(item._existing_additional_paths) ? item._existing_additional_paths : [];
// PROJ-113: the object's own main path is never an additional path
const newPaths = [...new Set([...existing, item.file_path])].filter(p => p !== item._weaviate_main_path);

try {
  await axios.patch(
    `${WEAVIATE}/v1/objects/${item._weaviate_class}/${item._weaviate_id}`,
    { properties: { additionalPaths: newPaths } },
    { headers: { 'Content-Type': 'application/json' }, timeout: 10000 }
  );
} catch(e) {
  throw new Error(`Weaviate PATCH failed for add_path (${item.file_hash}): ${e.message}`);
}

return [{ json: { ...item, _weaviate_patched: true, _new_additional_paths: newPaths } }];

const redis = require('redis');
const item = $input.first().json;
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await client.connect();
try {
  await client.hSet('alice:dms:path_to_hash', item.file_path, item.file_hash);
  await client.sAdd(`alice:dms:hash_to_paths:${item.file_hash}`, item.file_path);
} finally {
  await client.quit();
}
return [{ json: { ...item, _redis_updated: true } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-lifecycle", node: "Code: PATCH filePath" } });
const axios = require('axios');
const item = $input.first().json;
const WEAVIATE = 'http://weaviate:8080';

if (!item._weaviate_id || !item._weaviate_class) {
  logger.warn(`[alice-dms-lifecycle] update_path: no Weaviate object found for hash ${item.file_hash}, skipping PATCH`);
  return [{ json: { ...item, _weaviate_patched: false } }];
}

// PROJ-113: Image stores the main path in file_path; the new main path and the
// dead old paths must not remain in additionalPaths
const pathField = item._weaviate_path_field || 'filePath';
const oldPaths = Array.isArray(item.old_paths) ? item.old_paths : [];
const existing = Array.isArray(item._existing_additional_paths) ? item._existing_additional_paths : [];
const additionalPaths = existing.filter(p => p !== item.file_path && !oldPaths.includes(p));

try {
  await axios.patch(
    `${WEAVIATE}/v1/objects/${item._weaviate_class}/${item._weaviate_id}`,
    { properties: { [pathField]: item.file_path, additionalPaths } },
    { headers: { 'Content-Type': 'application/json' }, timeout: 10000 }
  );
} catch(e) {
  throw new Error(`Weaviate PATCH failed for update_path (${item.file_hash}): ${e.message}`);
}

return [{ json: { ...item, _weaviate_patched: true } }];

const redis = require('redis');
const item = $input.first().json;
const oldPaths = Array.isArray(item.old_paths) ? item.old_paths : [];
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await client.connect();
try {
  for (const op of oldPaths) {
    await client.hDel('alice:dms:path_to_hash', op);
    await client.sRem(`alice:dms:hash_to_paths:${item.file_hash}`, op);
  }
  await client.hSet('alice:dms:path_to_hash', item.file_path, item.file_hash);
  await client.sAdd(`alice:dms:hash_to_paths:${item.file_hash}`, item.file_path);
} finally {
  await client.quit();
}
return [{ json: { ...item, _redis_updated: true } }];

const errorData = $input.first().json;
const errorMsg = {
  workflow: 'alice-dms-lifecycle',
  error: errorData.execution?.error?.message || 'Unknown error',
  node: errorData.execution?.lastNodeExecuted || 'unknown',
  timestamp: new Date().toISOString(),
  execution_id: errorData.execution?.id || null
};
return [{ json: errorMsg }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-lifecycle", node: "Code: Handle delete_file" } });
const axios = require('axios');
const redis = require('redis');
const item = $input.first().json;
const WEAVIATE = 'http://weaviate:8080';
const THUMBNAILER = 'http://alice-dms-thumbnailer:8004';
const parentId = item._weaviate_id;
const parentClass = item._weaviate_class;

// PROJ-113: a failed lookup must not clean up Redis — the scanner re-reports
// the path on its next run.
if (item._lookup_error) {
  throw new Error('delete_file: Weaviate lookup failed for hash ' + item.file_hash + ' — Redis left unchanged');
}

let deletedTransactions = 0;
let deletedThumbnail = false;

if (!parentId || !parentClass) {
  // No Weaviate object for this hash — already cleaned up or never indexed
  logger.info('[alice-dms-lifecycle] delete_file: no Weaviate object for hash ' + item.file_hash + ' — cleaning up Redis only');
} else {
  // Cascade-delete BankTransaction children if parent is a BankStatement
  if (parentClass === 'BankStatement') {
    let cursor = null;
    const childUuids = [];
    for (let page = 0; page < 50; page++) {
      const afterClause = cursor ? (', after: "' + cursor + '"') : '';
      const q = '{ Get { BankTransaction(where: { path: ["parentStatementId"], operator: Equal, valueText: "' + parentId + '" }, limit: 100' + afterClause + ') { _additional { id } } } }';
      try {
        const r = await axios.post(WEAVIATE + '/v1/graphql', { query: q }, { headers: { 'Content-Type': 'application/json' }, timeout: 15000 });
        const hits = r.data && r.data.data && r.data.data.Get && r.data.data.Get.BankTransaction ? r.data.data.Get.BankTransaction : [];
        for (const h of hits) { if (h._additional && h._additional.id) childUuids.push(h._additional.id); }
        if (hits.length < 100) break;
        cursor = hits[hits.length - 1]._additional.id;
      } catch(e) {
        logger.warn('[alice-dms-lifecycle] GraphQL page ' + page + ' failed: ' + e.message);
        break;
      }
    }
    for (const uuid of childUuids) {
      try {
        await axios.delete(WEAVIATE + '/v1/objects/BankTransaction/' + uuid, { timeout: 10000 });
        deletedTransactions++;
      } catch(e) {
        logger.warn('[alice-dms-lifecycle] Failed to delete BankTransaction ' + uuid + ': ' + e.message);
      }
    }
    logger.info('[alice-dms-lifecycle] Deleted ' + deletedTransactions + ' BankTransaction children for ' + parentId);
  }

  // PROJ-113: delete the thumbnail file via the thumbnailer service (idempotent);
  // a failure never blocks the object delete.
  try {
    const tr = await axios.delete(THUMBNAILER + '/thumbnail/' + parentId, { timeout: 10000, validateStatus: () => true });
    deletedThumbnail = tr.status >= 200 && tr.status < 300 && !!(tr.data && tr.data.deleted);
  } catch(e) {
    logger.warn('[alice-dms-lifecycle] Thumbnail delete call failed for ' + parentId + ': ' + e.message);
  }

  // Delete parent object (404 = already gone, e.g. a parallel delete_file for another path of this hash)
  const dr = await axios.delete(WEAVIATE + '/v1/objects/' + parentClass + '/' + parentId, { timeout: 10000, validateStatus: () => true });
  if (!(dr.status >= 200 && dr.status < 300) && dr.status !== 404) {
    throw new Error('Failed to delete parent ' + parentClass + '/' + parentId + ': HTTP ' + dr.status);
  }
  logger.info('[alice-dms-lifecycle] Deleted parent ' + parentClass + '/' + parentId);
}

// PROJ-113: Weaviate is handled — now remove the dead path from the Redis truth
// (previously done by the scanner before publishing).
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await client.connect();
try {
  const current = await client.hGet('alice:dms:path_to_hash', item.file_path);
  if (current === item.file_hash) await client.hDel('alice:dms:path_to_hash', item.file_path);
  await client.sRem('alice:dms:hash_to_paths:' + item.file_hash, item.file_path);
  await client.sRem('alice:dms:processed', item.file_hash);
} finally {
  await client.quit();
}

return [{ json: { ...item, _deleted_statement: !!parentId, _deleted_transactions: deletedTransactions, _deleted_thumbnail: deletedThumbnail } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-lifecycle", node: "Code: Handle remove_path" } });
const axios = require('axios');
const fs = require('fs');
const redis = require('redis');
const item = $input.first().json;
const WEAVIATE = 'http://weaviate:8080';

// PROJ-113: one path of a file is gone, copies live on at other paths.
// Weaviate first (dead path out, a live path becomes main path if needed), then Redis.
if (item._lookup_error) {
  throw new Error('remove_path: Weaviate lookup failed for hash ' + item.file_hash + ' — Redis left unchanged');
}

const deadPath = item.file_path;
const alivePaths = (Array.isArray(item.alive_paths) ? item.alive_paths : [])
  .filter(p => p !== deadPath)
  .filter(p => { try { fs.accessSync(p, fs.constants.F_OK); return true; } catch(e) { return false; } })
  .sort();

let patched = false;
let newMainPath = item._weaviate_main_path || null;

if (!item._weaviate_id || !item._weaviate_class) {
  logger.info(`[alice-dms-lifecycle] remove_path: no Weaviate object for hash ${item.file_hash} — cleaning up Redis only`);
} else {
  const existing = Array.isArray(item._existing_additional_paths) ? item._existing_additional_paths : [];
  if (newMainPath === deadPath) {
    if (alivePaths.length === 0) {
      // No live copy left any more: leave the object alone, the next scan reports delete_file
      logger.warn(`[alice-dms-lifecycle] remove_path: main path ${deadPath} gone and no live copy found — Weaviate unchanged`);
      newMainPath = null;
    } else {
      newMainPath = alivePaths[0];
    }
  }
  if (newMainPath) {
    const additionalPaths = [...new Set([...existing, ...alivePaths])].filter(p => p !== newMainPath && p !== deadPath);
    const props = { [item._weaviate_path_field || 'filePath']: newMainPath, additionalPaths };
    if (item._weaviate_class !== 'Image' && newMainPath !== item._weaviate_main_path) {
      props.fileName = newMainPath.split('/').pop();
    }
    try {
      await axios.patch(
        `${WEAVIATE}/v1/objects/${item._weaviate_class}/${item._weaviate_id}`,
        { properties: props },
        { headers: { 'Content-Type': 'application/json' }, timeout: 10000 }
      );
      patched = true;
    } catch(e) {
      throw new Error(`Weaviate PATCH failed for remove_path (${item.file_hash}): ${e.message}`);
    }
    logger.info(`[alice-dms-lifecycle] remove_path: ${deadPath} removed from ${item._weaviate_class}/${item._weaviate_id}, main path ${newMainPath}`);
  }
}

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await client.connect();
try {
  const current = await client.hGet('alice:dms:path_to_hash', deadPath);
  if (current === item.file_hash) await client.hDel('alice:dms:path_to_hash', deadPath);
  await client.sRem('alice:dms:hash_to_paths:' + item.file_hash, deadPath);
} finally {
  await client.quit();
}

return [{ json: { ...item, _weaviate_patched: patched, _new_main_path: newMainPath } }];
